package io.github.jeshiomurmu.opencaller.core.testing

import io.github.jeshiomurmu.opencaller.core.model.Address
import io.github.jeshiomurmu.opencaller.core.model.PhoneNumber
import io.github.jeshiomurmu.opencaller.core.model.SenderId

/**
 * One message of the SMS corpus in `fixtures/sms_corpus/` (generated by `ml/sms-classifier/corpus/generate.py`; see
 * its README for the sources and the columns). Empty columns are `null`.
 */
data class CorpusMessage(
    val id: String,
    val template: String,
    val country: String,
    val lang: String,
    val category: String,
    val sender: String,
    val text: String,
    val otp: String?,
    val origin: String?,
    val appHash: String?,
    val expiryMinutes: Int?,
    val amount: String?,
    val currency: String?,
    val last4: String?,
    val merchant: String?,
) {
    /** The sender as the app sees it: a [PhoneNumber] when it has the E.164 shape, else a [SenderId]. */
    val address: Address get() = if (PhoneNumber.isE164(sender)) PhoneNumber(sender) else SenderId(sender)
}

/** Reads the SMS corpus splits (`train`, `val`, `test`; the test split holds templates no other split has). */
object SmsCorpus {
    /** The splits, in the order they are reported. */
    val SPLITS: List<String> = listOf("train", "val", "test")

    /** The messages of [split]. */
    fun load(split: String): List<CorpusMessage> {
        val stream =
            checkNotNull(SmsCorpus::class.java.getResourceAsStream("/fixtures/sms_corpus/$split.tsv")) {
                "Corpus split $split not found"
            }
        val lines = stream.bufferedReader(Charsets.UTF_8).use { it.readLines() }.filter(String::isNotEmpty)
        val columns = lines.first().split('\t')
        return lines.drop(1).map { line ->
            val values = line.split('\t')
            check(values.size == columns.size) { "Corpus row has ${values.size} columns, expected ${columns.size}" }
            row(columns.zip(values.map(::unescape)).toMap())
        }
    }

    private fun row(cells: Map<String, String>): CorpusMessage {
        fun cell(name: String): String? = cells.getValue(name).ifEmpty { null }
        return CorpusMessage(
            id = cells.getValue("id"),
            template = cells.getValue("template"),
            country = cells.getValue("country"),
            lang = cells.getValue("lang"),
            category = cells.getValue("category"),
            sender = cells.getValue("sender"),
            text = cells.getValue("text"),
            otp = cell("otp"),
            origin = cell("origin"),
            appHash = cell("app_hash"),
            expiryMinutes = cell("expiry_min")?.toInt(),
            amount = cell("amount"),
            currency = cell("currency"),
            last4 = cell("last4"),
            merchant = cell("merchant"),
        )
    }

    // The generator writes a line break as \n and a backslash as \\.
    private fun unescape(value: String): String {
        val out = StringBuilder(value.length)
        var i = 0
        while (i < value.length) {
            val c = value[i]
            if (c == '\\' && i + 1 < value.length) {
                out.append(if (value[i + 1] == 'n') '\n' else value[i + 1])
                i += 2
            } else {
                out.append(c)
                i++
            }
        }
        return out.toString()
    }
}
